// `bin/toli harness sync|status`: make the one lead contract (AGENTS.md) and the one skill/command source
// (.omp/skills, .omp/commands) load in every supported harness, and report which harness CLIs are ready.
//
// Shims are relative symlinks into .omp (one source of truth; omp de-duplicates same-file symlinks by realpath)
// plus a few generated files for harnesses that need their own format. `sync` is idempotent; `sync --check`
// reports drift without writing, and the test suite runs it against the repo so the shims never go stale.
import { lstatSync, mkdirSync, readFileSync, readlinkSync, rmSync, type Stats, symlinkSync } from "node:fs";
import { dirname, join } from "node:path";
import { Args } from "./args.ts";
import { GENERIC_NAMES, guidanceRules } from "./guidance.ts";
import { HARNESSES, harnessStatus } from "./harness.ts";
import { paths } from "./paths.ts";
import { out, printJson, ToliError, writeTextAtomic } from "./util.ts";

export type ShimItem =
    | { path: string; kind: "symlink"; target: string; why: string }
    | { path: string; kind: "file"; content: string; why: string };

const GENERATED = "Generated by `bin/toli harness sync`; edit src/harness-sync.ts, not this file.";

const CLAUDE_HOOK_MATCHER = "Edit|MultiEdit|Write|NotebookEdit|Read|Grep|Glob";

function hookCommand(name: string): { type: "command"; command: string; timeout: number } {
    return { type: "command", command: `"$CLAUDE_PROJECT_DIR"/bin/toli hook ${name}`, timeout: 30 };
}

function claudeSettings(): string {
    const settings = {
        hooks: {
            PreToolUse: [{ matcher: CLAUDE_HOOK_MATCHER, hooks: [hookCommand("claude-pre-tool")] }],
            UserPromptSubmit: [{ hooks: [hookCommand("claude-prompt")] }],
        },
    };
    return `${JSON.stringify(settings, null, 4)}\n`;
}

function cursorRule(): string {
    return [
        "---",
        "description: toli lead contract (AGENTS.md) and per-turn lead rules",
        "alwaysApply: true",
        "---",
        "",
        `<!-- ${GENERATED} -->`,
        "",
        "Follow AGENTS.md in this repository: it is toli's operating contract.",
        "If your prompt starts with `TOLI_BRIEF v1`, you are a jawan: do the brief and ignore the rules below.",
        "Otherwise you are the lead. Every turn:",
        "",
        ...guidanceRules(GENERIC_NAMES),
        "",
    ].join("\n");
}

/** Every shim, relative to toli's root. */
export function shimItems(): ShimItem[] {
    return [
        {
            path: "CLAUDE.md",
            kind: "file",
            content: `<!-- ${GENERATED} -->\n\n@AGENTS.md\n`,
            why: "Claude Code loads CLAUDE.md, which imports the AGENTS.md contract",
        },
        { path: ".claude/skills", kind: "symlink", target: "../.omp/skills", why: "Claude Code (and Grok) skills" },
        { path: ".claude/commands", kind: "symlink", target: "../.omp/commands", why: "Claude Code slash commands" },
        {
            path: ".claude/settings.json",
            kind: "file",
            content: claudeSettings(),
            why: "Claude Code hooks: lead guard (PreToolUse) and per-turn guidance + results (UserPromptSubmit)",
        },
        { path: ".agents/skills", kind: "symlink", target: "../.omp/skills", why: "Codex, pi and Cursor skills" },
        { path: ".cursor/commands", kind: "symlink", target: "../.omp/commands", why: "Cursor slash commands" },
        { path: ".cursor/rules/toli.mdc", kind: "file", content: cursorRule(), why: "Cursor always-apply lead rules" },
        { path: ".pi/prompts", kind: "symlink", target: "../.omp/commands", why: "pi prompt templates (commands)" },
    ];
}

export type SyncState = "ok" | "missing" | "differs" | "blocked";
export type SyncResult = { path: string; state: SyncState; action: "none" | "created" | "updated"; detail: string };

function currentState(root: string, item: ShimItem): { state: SyncState; detail: string } {
    const full = join(root, item.path);
    let stat: Stats;
    try {
        stat = lstatSync(full);
    } catch {
        return { state: "missing", detail: "absent" };
    }
    if (item.kind === "symlink") {
        if (!stat.isSymbolicLink())
            return { state: "blocked", detail: "a real file or directory is in the way; move it aside, then re-run" };
        const target = readlinkSync(full);
        return target === item.target
            ? { state: "ok", detail: `-> ${target}` }
            : { state: "differs", detail: `-> ${target}` };
    }
    if (stat.isSymbolicLink() || !stat.isFile()) return { state: "blocked", detail: "not a regular file" };
    return readFileSync(full, "utf8") === item.content
        ? { state: "ok", detail: "up to date" }
        : { state: "differs", detail: "content differs from the generator" };
}

/** Bring every shim up to date under `root` (or only report with `check`). Never deletes real files or dirs. */
export function syncShims(root: string, check: boolean): SyncResult[] {
    return shimItems().map((item): SyncResult => {
        const { state, detail } = currentState(root, item);
        if (check || state === "ok" || state === "blocked") return { path: item.path, state, action: "none", detail };
        const full = join(root, item.path);
        mkdirSync(dirname(full), { recursive: true });
        if (item.kind === "symlink") {
            if (state === "differs") rmSync(full);
            symlinkSync(item.target, full);
        } else {
            writeTextAtomic(full, item.content);
        }
        return {
            path: item.path,
            state,
            action: state === "missing" ? "created" : "updated",
            detail: item.kind === "symlink" ? `-> ${item.target}` : "written",
        };
    });
}

function sync(argv: string[]): void {
    const args = new Args(argv, { booleans: ["check", "json"] });
    args.maxPositional(0);
    const check = args.bool("check");
    const results = syncShims(paths.root(), check);
    if (args.bool("json")) printJson(results);
    else
        for (const result of results)
            out(`${result.action === "none" ? result.state : result.action} ${result.path} ${result.detail}`);
    const bad = results.filter((result) => result.state === "blocked" || (check && result.state !== "ok"));
    if (bad.length > 0)
        throw new ToliError(
            check
                ? `${bad.length} harness shim${bad.length === 1 ? "" : "s"} out of date: run \`bin/toli harness sync\``
                : `${bad.length} harness shim${bad.length === 1 ? "" : "s"} blocked by existing files`,
        );
}

function status(argv: string[]): void {
    const args = new Args(argv, { booleans: ["json"] });
    args.maxPositional(0);
    const statuses = HARNESSES.map(harnessStatus);
    if (args.bool("json")) {
        printJson(statuses);
        return;
    }
    for (const entry of statuses) {
        const login = entry.loggedIn === null ? "login unknown" : entry.loggedIn ? "logged in" : "NOT logged in";
        out(
            entry.installed
                ? `${entry.harness}\tinstalled ${entry.version ?? "(version unknown)"}\t${login}: ${entry.detail}`
                : `${entry.harness}\t${entry.detail}`,
        );
    }
}

export function harnessCommand(argv: string[]): void {
    const [sub, ...rest] = argv;
    switch (sub) {
        case "sync":
            sync(rest);
            return;
        case "status":
            status(rest);
            return;
        default:
            throw new ToliError("usage: toli harness sync [--check] [--json] | status [--json]");
    }
}
